            attachments: std::mem::take(&mut self.attachments),
            tab: self.selected_tab,
        };
        for text in attached_text {
            self.attach_text(text, cx);
        }
        for image in attached_images {
            self.attach_image(image, cx);
        }
        for file in attached_files {
            self.attach_file(file, cx);
        }
        let tab = TABS
            .iter()
            .position(|tab| *tab == mode)
            .unwrap_or(DEFAULT_TAB);
        self.put_back(text.clone(), tab, window, cx);
        self.recalled = None;
        self.editing = Some(Editing {
            position,
            set_aside,
            text,
        });
        cx.notify();
    }

    /// Puts a prompt sent before back in the input as a new prompt, as <Up>
    /// brings it back: its text as typed, its attachments, its mode's tab
    /// selected, the cursor at the end; or, with none, empties the input.
    pub fn recall(
        &mut self,
        prompt: Option<Recalled>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.attachments.clear();
        let Some((text, mode, attached_text, attached_images, attached_files)) = prompt else {
            self.recalled = None;
            let tab = self.selected_tab;
            self.put_back(String::new(), tab, window, cx);
            cx.notify();
            return;
        };
        for text in attached_text {
            self.attach_text(text, cx);
        }
        for image in attached_images {
            self.attach_image(image, cx);
        }
        for file in attached_files {
            self.attach_file(file, cx);
        }
        let tab = TABS
            .iter()
            .position(|tab| *tab == mode)
            .unwrap_or(self.selected_tab);
        self.put_back(text.clone(), tab, window, cx);
        self.recalled = Some(text);
        cx.notify();
    }

    /// What <Up>, `back`, or <Down> does in the text input, if it goes
    /// through what was sent rather than moving the cursor: from an empty
    /// input, with nothing attached, <Up> starts afresh; on a queued prompt
    /// being edited, or a prompt brought back, still unchanged, <Up> on its
    /// first line and <Down> on its last step along.
    fn recall_for(&self, back: bool, cx: &App) -> Option<Recall> {
        if self.preview.is_some() || self.send_menu.is_some() || self.completion.read(cx).is_open() {
            return None;
        }
        let editor = self.editor.read(cx);
        let value = editor.value();
        let from = self
            .editing
            .as_ref()
            .map(|editing| editing.text.as_str())
            .or(self.recalled.as_deref());
        if value.is_empty() && self.attachments.is_empty() && self.editing.is_none() {
            return back.then_some(Recall { back, fresh: true });
        }
        if from != Some(value.as_ref()) {
            return None;
        }
        let cursor = editor.cursor().min(value.len());
        let on_edge = if back {
            !value[..cursor].contains('\n')
        } else {
            !value[cursor..].contains('\n')
        };
        on_edge.then_some(Recall { back, fresh: false })
    }

    /// Cancels editing a queued prompt, if one is being edited, bringing back
    /// what was set aside.
    pub fn cancel_editing(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.end_editing(window, cx) {
            cx.emit(QueuedEdit::Cancelled);
        }
    }

    /// Brings back what editing set aside; whether a prompt was being edited.
    fn end_editing(&mut self, window: &mut Window, cx: &mut Context<Self>) -> bool {
        let Some(editing) = self.editing.take() else {
            return false;
        };
        let SetAside {
            text,
            attachments,
            tab,
        } = editing.set_aside;
        self.attachments = attachments;
        self.put_back(text, tab, window, cx);
        cx.notify();
        true
    }

    /// Puts `text` in the input, the cursor at its end, in the tab at `tab`,
    /// with focus.
    fn put_back(&mut self, text: String, tab: usize, window: &mut Window, cx: &mut Context<Self>) {
        if tab != self.selected_tab {
            self.move_tint(tab as isize - self.selected_tab as isize);
            self.selected_tab = tab;
            cx.emit(TabChanged);
        }
        self.editor.update(cx, |editor, cx| {
            use gpui_kit::component::input::RopeExt as _;
            editor.set_value(text, window, cx);
            let end = editor.text().offset_to_position(editor.text().len());
            editor.set_cursor_position(end, window, cx);
        });
        self.editor.read(cx).focus_handle(cx).focus(window, cx);
    }

    /// Where in the queue the prompt being edited is, counted from 1.
    pub fn set_editing_position(&mut self, position: usize, cx: &mut Context<Self>) {
        if let Some(editing) = &mut self.editing
            && editing.position != position
        {
            editing.position = position;
            cx.notify();
        }
    }

    /// Whether a queued prompt is being edited.
    #[cfg(test)]
    pub fn is_editing(&self) -> bool {
        self.editing.is_some()
    }

    /// Sends the prompt, `how` it is sent; while a queued prompt is being
    /// edited, saves the edit instead.
    fn send(&mut self, how: Sent, window: &mut Window, cx: &mut Context<Self>) {
        let text = self.editor.read(cx).value().to_string();
        if text.is_empty() {
            return;
        }
        if self.editing.is_some() {
            let (attached_text, attached_images, attached_files) =
                split_attachments(std::mem::take(&mut self.attachments));
            let mode = TABS[self.selected_tab];
            self.end_editing(window, cx);
            cx.emit(QueuedEdit::Saved {
                text,
                mode,
                attached_text,
                attached_images,
                attached_files,
            });
            return;
        }
        // Sent from the preview, the text input comes back, empty.
        self.send_menu = None;
        if self.preview.take().is_some() {
            self.editor.read(cx).focus_handle(cx).focus(window, cx);
        }
        self.editor
            .update(cx, |editor, cx| editor.set_value("", window, cx));
        self.recalled = None;
        // The attachments go with the prompt.
        let (attached_text, attached_images, attached_files) =
            split_attachments(std::mem::take(&mut self.attachments));
        cx.emit(Submit {
            text,
            mode: TABS[self.selected_tab],
            attached_text,
            attached_images,
            attached_files,
            queue: how == Sent::Queued,
            to_task: how == Sent::ToTask,
        });
        // A prompt from an answer's card sent, what was set aside for it
        // comes back.
        if let Some(text) = self.set_aside_text.take() {
            let tab = self.selected_tab;
            self.put_back(text, tab, window, cx);
        }
    }

